---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Status pill: One live line for what the agent is doing right now.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change status-pill.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './status-pill.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="status-pill" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="spl dm">
  <div class="spl-stage dm-main">
    <div class="spl-pill" aria-live="polite"><div class="spl-in"></div></div>
  </div>
  <div class="demo"><div class="seg2" role="group" aria-label="Variant"><button aria-pressed="true" data-v="pill">Pill</button><button aria-pressed="false" data-v="bar">Bar</button></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './status-pill.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Status pill ---------- */
.spl-stage{min-height:44px;justify-content:center}
.spl-pill{background:var(--dm-surface);border-radius:var(--dm-r-pill);box-shadow:var(--dm-shadow);height:40px;display:flex;align-items:center;overflow:hidden;transition:width .6s var(--dm-ease),border-radius .5s var(--dm-ease),height .5s var(--dm-ease)}
.spl-in{display:flex;align-items:center;gap:9px;padding:0 6px 0 14px;height:100%;white-space:nowrap;font-size:13.5px;transition:opacity .32s var(--dm-ease),filter .32s var(--dm-ease)}
.spl-in.out{opacity:0;filter:blur(4px);transition-duration:.16s}
/* the mark's box is the mark itself, so the room before it is the pill's own padding, the same as the room after the words
   (owner, 21 Nov: "too much on left vs right visually"): a pale dot no longer sits 5px further in than a spinner */
.spl-in .g{display:grid;place-items:center;min-width:6px;color:var(--dm-fg2)}
.spl-in .m{color:var(--dm-muted);font-variant-numeric:tabular-nums}
.spl-in .end{width:0}
.spl-in>:is(.g,.m,.fchip,.pill){flex:none}
.spl-in>span:not(.g,.m,.end,.fchip){min-width:0;overflow:hidden;text-overflow:ellipsis}
.spl-in .pill{height:28px;margin-left:var(--dm-s-1)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.spl .pill:active{transform:none}
/* the bar is a small card: its line and the track under it sit 16px in from every edge (owner, 18 Nov). Its line is as tall
   as its words, or as Review while Review is there, so it grows a little round the button and shrinks back after, smoothly,
   and keeps no room for it otherwise */
.spl.bar .spl-pill{--dm-spl-row:18px;border-radius:var(--dm-r-card);height:calc(var(--dm-spl-row) + 45px);align-items:flex-start}
.spl.bar .spl-pill:has(.spl-in .pill){--dm-spl-row:28px}
.spl.bar .spl-in{height:var(--dm-spl-row);margin-top:16px;width:100%;padding:0 var(--dm-s-4);line-height:18px}
.spl.bar .spl-in .m,.spl.bar .spl-in .pill{margin-left:auto}
.spl.bar .spl-in .end{display:none}
.spl-track{position:absolute;left:16px;right:16px;bottom:16px;height:3px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-rail);overflow:hidden;opacity:0;transition:opacity .16s}
.spl.bar .spl-track{opacity:1;transition:opacity .4s var(--dm-ease) .1s}
.spl.mo .spl-track{opacity:0;transition:opacity .16s}
.spl-fill{height:100%;width:0;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transition:width .8s var(--dm-ease)}
.spl-pill{position:relative}
/* Clean (owner, 17 Nov): a hairline pill, 36px, with the card's outline and short shadow; the marks keep their colours
   (the blue spinner and fill, the green tick, the orange wait dot). A step crosses with a 3px fade, no blur; Review is the
   ink button, round and concentric in the pill. The bar takes the card's round corners, its content 16px in from every edge
   (owner, 18 Nov), a 3px rail with the accent fill, and Review a 28px pill */
:root[data-style="clean"] .spl-stage,:root [data-style="clean"] .spl-stage,:root [data-style="clean"].spl-stage{min-height:40px}
/* its hairline at half the card's (owner, 21 Nov: "reducing opacity on the border by 50% on clean") */
:root[data-style="clean"] .spl-pill,:root [data-style="clean"] .spl-pill,:root [data-style="clean"].spl-pill{height:36px;border-radius:999px;background:var(--dm-surface);box-shadow:0 0 0 1px rgba(0,0,0,.035),0 1px 1px rgba(0,0,0,.04),0 2px 10px -4px rgba(0,0,0,.12);transition:width var(--dm-t) var(--dm-ease),border-radius .42s var(--dm-ease),height .42s var(--dm-ease)}
:root[data-style="clean"][data-theme="dark"] .spl-pill,:root[data-theme="dark"] [data-style="clean"] .spl-pill,:root[data-theme="dark"] [data-style="clean"].spl-pill{box-shadow:0 0 0 1px rgba(255,255,255,.05),0 1px 1px rgba(0,0,0,.5),0 2px 10px -4px rgba(0,0,0,.6)}
@media (prefers-color-scheme:dark){:root[data-style="clean"]:not([data-theme="light"]) .spl-pill,:root:not([data-theme="light"]) [data-style="clean"] .spl-pill,:root:not([data-theme="light"]) [data-style="clean"].spl-pill{box-shadow:0 0 0 1px rgba(255,255,255,.05),0 1px 1px rgba(0,0,0,.5),0 2px 10px -4px rgba(0,0,0,.6)}}
:root[data-style="clean"] .spl-in,:root [data-style="clean"] .spl-in,:root [data-style="clean"].spl-in{gap:8px;padding:0 5px 0 13px;font-size:13px;color:var(--dm-fg);transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .spl-in.out,:root [data-style="clean"] .spl-in.out,:root [data-style="clean"].spl-in.out{opacity:0;filter:none;transform:translateY(-3px);transition:opacity .15s ease-in-out,transform .15s ease-in-out}
:root[data-style="clean"] .spl-in .m,:root [data-style="clean"] .spl-in .m,:root [data-style="clean"].spl-in .m{color:var(--dm-muted)}
:root[data-style="clean"] .spl-in .pill,:root [data-style="clean"] .spl-in .pill,:root [data-style="clean"].spl-in .pill{height:26px;padding:0 11px;border-radius:999px;margin-left:2px}
:root[data-style="clean"] .spl.bar .spl-pill,:root [data-style="clean"] .spl.bar .spl-pill,:root [data-style="clean"].spl.bar .spl-pill{height:calc(var(--dm-spl-row) + 45px);border-radius:var(--dm-r-card)}
:root[data-style="clean"] .spl.bar .spl-in,:root [data-style="clean"] .spl.bar .spl-in,:root [data-style="clean"].spl.bar .spl-in{height:var(--dm-spl-row);padding:0 16px}
:root[data-style="clean"] .spl.bar .spl-in .pill,:root [data-style="clean"] .spl.bar .spl-in .pill,:root [data-style="clean"].spl.bar .spl-in .pill{height:28px;padding:0 12px;margin-left:auto}
/* the measure under the bar: it lets the pointer through */
:root[data-style="clean"] .spl-track,:root [data-style="clean"] .spl-track,:root [data-style="clean"].spl-track{left:16px;right:16px;bottom:16px;height:3px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-rail);pointer-events:none}
:root[data-style="clean"] .spl-fill,:root [data-style="clean"] .spl-fill,:root [data-style="clean"].spl-fill{background:var(--dm-accent-mark);transition:width .6s var(--dm-ease)}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] :is(.spl-pill,.spl-in,.spl-in.out,.spl-fill),:root [data-style="clean"] :is(.spl-pill,.spl-in,.spl-in.out,.spl-fill),:root [data-style="clean"]:is(.spl-pill,.spl-in,.spl-in.out,.spl-fill){transition:none!important}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, DM, I, REDUCE, seg } from '../core/core.js';
DM.def('status-pill', (r, c) => {
  const pill = $('.spl-pill', r), box = $('.spl-in', r), root = $('.spl', r);
  pill.insertAdjacentHTML('beforeend', '<div class="spl-track"><div class="spl-fill"></div></div>');
  const fill = $('.spl-fill', r);
  // the switch morphs in three beats, so the words and the shape never move at once: the line fades out with its track,
  // the pill changes shape while it's empty, then the new layout fades in with the track under it
  let morph = 0;
  seg($('.seg2', r), v => {
    const bar = v === 'bar', id = ++morph; if (root.classList.contains('bar') === bar) return;
    pill.style.width = pill.offsetWidth + 'px'; box.classList.add('out'); root.classList.add('mo');
    c.later(REDUCE ? 0 : 170, () => { if (id !== morph) return; root.classList.toggle('bar', bar); fit(); });
    c.later(REDUCE ? 0 : 430, () => { if (id !== morph) return; morph = 0; box.classList.remove('out'); root.classList.remove('mo'); });
  });
  /* both variants hug their content; the bar keeps a little extra room for its track. Neither is ever wider than the room
     it has (a phone): its words give way with an ellipsis */
  function fit(){
    box.style.width = 'max-content'; const w = box.scrollWidth; box.style.width = '';
    pill.style.width = Math.min(root.classList.contains('bar') ? Math.max(w + 24, 300) : w, pill.parentElement.clientWidth || Infinity) + 'px';
  }
  function set(htmlStr, pct){
    pill.style.width = pill.offsetWidth + 'px';
    box.classList.add('out');
    // mid-switch, the morph brings the line back once the shape has settled
    c.later(180, () => { box.innerHTML = htmlStr; if (!morph) box.classList.remove('out'); fit(); });
    if (pct !== undefined) fill.style.width = pct + '%';
  }
  const think = '<span class="think on"><i></i><i></i><i></i><i></i></span>';
  box.innerHTML = '<span class="g"><span class="dot" style="color:var(--dm-faint)"></span></span><span class="fg2">Ready for a task</span><span class="end"></span>';
  requestAnimationFrame(fit);
  // and it fits again when its room changes
  if (window.ResizeObserver){ let rw = 0; const ro = new ResizeObserver(([e]) => { const w = Math.round(e.contentRect.width); if (w !== rw){ rw = w; fit(); } }); ro.observe(pill.parentElement); c.offs.push(() => ro.disconnect()); }
  const idle = '<span class="g"><span class="dot" style="color:var(--dm-faint)"></span></span><span class="fg2">Ready for a task</span><span class="end"></span>';
  c.run(async () => { for (;;){
    await c.wait(1100);
    set(`<span class="g" style="color:var(--dm-fg)">${think}</span><span class="shim">Thinking</span><span class="end"></span>`, 8); await c.wait(1800);
    set(`<span class="g" style="color:var(--dm-fg)"><span class="radar"></span></span><span class="shim">Reading Figma frames</span><span class="m n">1 of 4</span><span class="end"></span>`, 22);
    await c.wait(400);
    // the count ticks over in place, under a steady line
    for (let i = 2; i <= 4; i++){ await c.wait(650); const n = $('.n', box); if (n) n.textContent = i + ' of 4'; fill.style.width = (22 + i * 8) + '%'; }
    await c.wait(700);
    set(`<span class="g" style="color:var(--dm-fg)"><span class="spin"></span></span><span class="shim">Editing</span><span class="fchip" style="height:24px"><span class="ft re">TSX</span>PricingCard.tsx</span><span class="end"></span>`, 64); await c.wait(2000);
    set(`<span class="g" style="color:var(--dm-warn-mark)"><span class="dot"></span></span><span>Waiting for your approval</span><button class="pill primary sm">Review</button>`, 72);
    /* waits for Review, and carries on by itself after a while so the loop never stalls; once you have taken over, it waits for you */
    await new Promise(res => { c.later(220, () => { const b = $('.pill', box); if (b) b.onclick = res; }); c.auto(8000, res); });
    set(`<span class="g" style="color:var(--dm-fg)"><span class="spin"></span></span><span class="shim">Applying 4 changes</span><span class="end"></span>`, 88); await c.wait(1600);
    // done is a neutral line with the green tick (the mark green), and no elapsed time (owner, 18 Nov)
    set(`<span class="g" style="color:var(--dm-ok-mark)">${I('ok')}</span><span>Done</span><span class="m">4 files changed</span><span class="end"></span>`, 100);
    await c.wait(3200); set(idle, 0);
  } });
});
